#!/usr/bin/env python3
"""Load selected Eurostat-style indicators into normalized long format."""

import csv
import json
import os
import sys


def find_column(row, candidates):
    """Find the first matching column name from candidates in row keys."""
    for c in candidates:
        if c in row:
            return c
    # Case-insensitive fallback
    row_keys_lower = {k.lower(): k for k in row}
    for c in candidates:
        if c.lower() in row_keys_lower:
            return row_keys_lower[c.lower()]
    return None


def load_selected_indicators(path):
    """Load selected indicators and return dict of indicator_id -> {indicator_name, unit}."""
    selected = {}
    with open(path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            ind_id_col = find_column(row, ['indicator_id', 'id', 'code', 'indicator_code'])
            ind_name_col = find_column(row, ['indicator_name', 'name', 'label', 'description'])
            unit_col = find_column(row, ['unit', 'unit_of_measure', 'unit_of_measurement'])

            if ind_id_col is None:
                continue

            indicator_id = row.get(ind_id_col, '').strip()
            indicator_name = row.get(ind_name_col, '').strip() if ind_name_col else ''
            unit = row.get(unit_col, '').strip() if unit_col else ''

            if indicator_id:
                selected[indicator_id] = {
                    'indicator_name': indicator_name,
                    'unit': unit,
                }
    return selected


def load_api_config(path):
    """Load API config JSON for potential unit/mapping overrides."""
    try:
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}


def is_numeric(value):
    """Check if a string value is numeric."""
    if value is None:
        return False
    value = str(value).strip()
    if value == '':
        return False
    try:
        float(value)
        return True
    except (ValueError, TypeError):
        return False


def clean_numeric(value):
    """Clean a numeric value string."""
    value = str(value).strip().replace(',', '')
    try:
        f = float(value)
        if f == int(f) and '.' not in value:
            return str(int(f))
        return str(f)
    except (ValueError, TypeError):
        return value


def main():
    # Determine base directory (workspace root)
    script_dir = os.path.dirname(os.path.abspath(__file__))
    base_dir = os.path.dirname(script_dir)

    selected_indicators_path = os.path.join(base_dir, 'outputs', 't01_selected_indicators.csv')
    api_config_path = os.path.join(base_dir, 'inputs', 'eurostat', 'sample_api_config.json')
    city_values_path = os.path.join(base_dir, 'inputs', 'eurostat', 'eurostat_city_values_sample.csv')
    output_path = os.path.join(base_dir, 'outputs', 't02_eurostat_raw.csv')

    # Load selected indicators
    selected = load_selected_indicators(selected_indicators_path)
    if not selected:
        print("Warning: No selected indicators found.", file=sys.stderr)

    # Load API config for potential unit overrides
    api_config = load_api_config(api_config_path)

    # Check if API config has unit mappings
    api_units = {}
    if isinstance(api_config, dict):
        # Look for unit mappings in various possible keys
        for key in ['units', 'unit_mappings', 'indicator_units', 'metadata']:
            if key in api_config and isinstance(api_config[key], dict):
                for k, v in api_config[key].items():
                    if isinstance(v, dict) and 'unit' in v:
                        api_units[k] = v['unit']
                    elif isinstance(v, str):
                        api_units[k] = v

    # Load city values and filter
    rows = []
    with open(city_values_path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            ind_id_col = find_column(row, ['indicator_id', 'id', 'code', 'indicator_code'])
            city_id_col = find_column(row, ['city_id', 'city', 'city_code', 'location'])
            city_name_col = find_column(row, ['city_name', 'city', 'location_name', 'name'])
            year_col = find_column(row, ['year', 'time', 'time_period', 'period'])
            value_col = find_column(row, ['value', 'obs_value', 'data_value', 'amount'])

            if ind_id_col is None:
                continue

            indicator_id = row.get(ind_id_col, '').strip()

            # Only include selected indicators
            if indicator_id not in selected:
                continue

            city_id = row.get(city_id_col, '').strip() if city_id_col else ''
            city_name = row.get(city_name_col, '').strip() if city_name_col else ''
            year = row.get(year_col, '').strip() if year_col else ''
            value = row.get(value_col, '').strip() if value_col else ''

            # Only include numeric values
            if not is_numeric(value):
                continue

            # Clean value
            value = clean_numeric(value)

            # Get indicator info
            info = selected[indicator_id]
            indicator_name = info['indicator_name']
            unit = info['unit']

            # Override unit from API config if available
            if indicator_id in api_units:
                unit = api_units[indicator_id]

            rows.append({
                'city_id': city_id,
                'city_name': city_name,
                'year': year,
                'indicator_id': indicator_id,
                'indicator_name': indicator_name,
                'value': value,
                'unit': unit,
            })

    # Deduplicate by (city_id, year, indicator_id)
    seen = set()
    unique_rows = []
    for row in rows:
        key = (row['city_id'], row['year'], row['indicator_id'])
        if key not in seen:
            seen.add(key)
            unique_rows.append(row)

    # Ensure output directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    # Write output CSV (RFC 4180 compliant via csv module)
    fieldnames = ['city_id', 'city_name', 'year', 'indicator_id', 'indicator_name', 'value', 'unit']
    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(
            f,
            fieldnames=fieldnames,
            quoting=csv.QUOTE_MINIMAL,
            lineterminator='\r\n',
        )
        writer.writeheader()
        for row in unique_rows:
            writer.writerow(row)

    print(f"Wrote {len(unique_rows)} rows to {output_path}")


if __name__ == '__main__':
    main()
